package com.combinationrunes;

import java.util.HashMap;
import java.util.Map;

import lombok.Getter;
import net.runelite.api.ItemID;

public enum CombinationRune {
    MIST(ItemID.MIST_RUNE, ElementalRune.AIR, ElementalRune.WATER),
    DUST(ItemID.DUST_RUNE, ElementalRune.AIR, ElementalRune.EARTH),
    MUD(ItemID.MUD_RUNE, ElementalRune.WATER, ElementalRune.EARTH),
    SMOKE(ItemID.SMOKE_RUNE, ElementalRune.AIR, ElementalRune.FIRE),
    STEAM(ItemID.STEAM_RUNE, ElementalRune.WATER, ElementalRune.FIRE),
    LAVA(ItemID.LAVA_RUNE, ElementalRune.EARTH, ElementalRune.FIRE);

    @Getter
    private final int itemId;
    @Getter
    private final ElementalRune firstElement;
    @Getter
    private final ElementalRune secondElement;

    CombinationRune(final int itemId, final ElementalRune firstElement, final ElementalRune secondElement) {
        this.itemId = itemId;
        this.firstElement = firstElement;
        this.secondElement = secondElement;
    }

    private static final Map<Integer, CombinationRune> BY_ID = new HashMap<>();

    static {
        for (CombinationRune r : values()) {
            BY_ID.put(r.itemId, r);
        }
    }

    static CombinationRune of(int id) {
        return BY_ID.get(id);
    }
}

package com.combinationrunes;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("combinationrunes")
public interface CombinationRunesIdentifierConfig extends Config {

    String SECTION_DESCRIPTION_GENERAL = "Combination Runes Identifier settings";

    String ITEM_DESCRIPTION_SHOW_OVERLAY = "Enable/Disable overlay on combination runes";
    String ITEM_DESCRIPTION_COLORED_SYMBOLS = "Enable/Disable color for elemental rune symbols";
    String ITEM_DESCRIPTION_SHOW_IN_INVENTORY = "Enable/Disable overlay in inventory";

    @ConfigSection(name = "General", description = SECTION_DESCRIPTION_GENERAL, position = 0)
    String generalSection = "generalSection";

    @ConfigItem(keyName = "showOverlay", name = "Show overlay", description = ITEM_DESCRIPTION_SHOW_OVERLAY, position = 0, section = generalSection)
    default boolean showOverlay() {
        return true;
    }

    @ConfigItem(keyName = "coloredSymbols", name = "Colored symbols", description = ITEM_DESCRIPTION_COLORED_SYMBOLS, position = 1,
            section = generalSection)
    default boolean coloredSymbols() {
        return true;
    }

    @ConfigItem(keyName = "showInInventory", name = "Show overlay in inventory", description = ITEM_DESCRIPTION_SHOW_IN_INVENTORY, position = 2,
            section = generalSection)
    default boolean showInInventory() {
        return false;
    }
}

package com.combinationrunes;

import java.awt.*;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

@Singleton
public class CombinationRunesIdentifierOverlay extends WidgetItemOverlay {

    private final static String GAP = "     ";
    private final static int COORDINATE_OFFSET_X = 2;
    private final static int COORDINATE_OFFSET_Y = 2;
    private static final int WIDGET_ID_COMPONENT_BITS = 16;

    private final CombinationRunesIdentifierConfig config;
    private final ItemManager itemManager;

    @Inject
    CombinationRunesIdentifierOverlay(CombinationRunesIdentifierConfig config, ItemManager itemManager) {
        this.config = config;
        this.itemManager = itemManager;

        showOnBank();
        showOnInventory();
    }

    @Override
    public void renderItemOverlay(final Graphics2D graphics, final int itemId, final WidgetItem widgetItem) {
        if (!showOverlay(widgetItem)) {
            return;
        }

        CombinationRune rune = CombinationRune.of(itemManager.canonicalize(itemId));

        if (rune == null) {
            return;
        }

        drawLetters(graphics, widgetItem.getCanvasBounds(), rune);
    }

    private boolean showOverlay(final WidgetItem widgetItem) {
        if (!config.showOverlay()) {
            return false;
        }

        if (!config.showInInventory() && isInventoryItem(widgetItem)) {
            return false;
        }

        return true;
    }

    private boolean isInventoryItem(final WidgetItem widgetItem) {
        Widget widget = widgetItem.getWidget();

        if (widget == null) {
            return false;
        }

        int groupId = widget.getId() >>> WIDGET_ID_COMPONENT_BITS;
        return groupId == InterfaceID.INVENTORY;
    }

    private void drawLetters(Graphics2D graphics, Rectangle canvasBounds, CombinationRune rune) {
        graphics.setFont(FontManager.getRunescapeSmallFont());
        FontMetrics fontMetrics = graphics.getFontMetrics();

        String firstElementSymbol = rune.getFirstElement().getSymbol();
        String secondElementSymbol = rune.getSecondElement().getSymbol();

        int totalWidth = fontMetrics.stringWidth(firstElementSymbol + GAP + secondElementSymbol);
        int x = canvasBounds.x + ((canvasBounds.width - totalWidth) / 2) - COORDINATE_OFFSET_X;
        int y = canvasBounds.y + canvasBounds.height - COORDINATE_OFFSET_Y;

        drawShadowed(graphics, firstElementSymbol, x, y, rune.getFirstElement().getColor());
        x += fontMetrics.stringWidth(firstElementSymbol + GAP);
        drawShadowed(graphics, secondElementSymbol, x, y, rune.getSecondElement().getColor());
    }

    private void drawShadowed(Graphics2D graphics, String text, int x, int y, Color color) {
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 1, y + 1);

        graphics.setColor(config.coloredSymbols() ? color : Color.WHITE);
        graphics.drawString(text, x, y);
    }
}

package com.combinationrunes;

import com.google.inject.Provides;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Combination Runes Identifier")
public class CombinationRunesIdentifierPlugin extends Plugin {

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private CombinationRunesIdentifierOverlay combinationRunesOverlay;

    @Override
    protected void startUp() throws Exception {
        overlayManager.add(combinationRunesOverlay);
    }

    @Override
    protected void shutDown() throws Exception {
        overlayManager.remove(combinationRunesOverlay);
    }

    @SuppressWarnings("unused")
    @Provides
    CombinationRunesIdentifierConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(CombinationRunesIdentifierConfig.class);
    }
}

package com.combinationrunes;

import java.awt.*;

import lombok.Getter;
